\set QUIET on
\set VERBOSITY verbose
\set ON_ERROR_STOP on
\set ECHO none
\pset pager off
\pset format unaligned
\pset tuples_only on
\pset footer off
\pset expanded off
\timing off
SET client_min_messages = warning;
\echo 'pg-glibc-audit confirmation|bb712fbf2453edabbb48a17a5660c678956bc83174b77dac249f3e1833a07197|UTF8'
SELECT 'database encoding|' || getdatabaseencoding();
SELECT 'server|' || current_setting('server_version');
SELECT getdatabaseencoding() = 'UTF8' AS encoding_ok \gset
\if :encoding_ok
\else
\quit
\endif
-- collation C.utf8: C.utf8
\unset c1
\set ON_ERROR_STOP off
SELECT ('a' < 'b' COLLATE "C.utf8") IS NOT NULL AS c1 \gset
\set ON_ERROR_STOP on
\if :{?c1}
SELECT 'collation|C.utf8|usable|glibc ' || coalesce((SELECT pg_collation_actual_version(c.oid) FROM pg_collation c WHERE c.collname = 'C.utf8' AND c.collencoding IN (-1, (SELECT encoding FROM pg_database WHERE datname = current_database())) AND pg_collation_is_visible(c.oid)), 'NULL');
SELECT 'test|' || id || '|C.utf8|' || r || '|old ' || o || ', new ' || n || '|' || CASE m WHEN 'both' THEN 'measured on both machines' WHEN 'old' THEN 'measured on the old machine, the new one by the characters between' WHEN 'new' THEN 'measured on the new machine, the old one by the characters between' WHEN 'table' THEN 'from both machines'' compiled sort tables' END || '|' || CASE WHEN r = o THEN 'like the OLD machine' WHEN r = n THEN 'like the NEW machine' ELSE 'like NEITHER machine' END
FROM (SELECT id, o, n, m, CASE WHEN a < b COLLATE "C.utf8" THEN '<' WHEN a > b COLLATE "C.utf8" THEN '>' ELSE '=' END AS r
