-- collation ko_KR: ko_KR.utf8
\unset c2
\set ON_ERROR_STOP off
SELECT ('a' < 'b' COLLATE "ko_KR") IS NOT NULL AS c2 \gset
\set ON_ERROR_STOP on
\if :{?c2}
SELECT 'collation|ko_KR|usable|glibc ' || coalesce((SELECT pg_collation_actual_version(c.oid) FROM pg_collation c WHERE c.collname = 'ko_KR' AND c.collencoding IN (-1, (SELECT encoding FROM pg_database WHERE datname = current_database())) AND pg_collation_is_visible(c.oid)), 'NULL');
SELECT 'test|' || id || '|ko_KR|' || r || '|old ' || o || ', new ' || n || '|' || CASE m WHEN 'both' THEN 'measured on both machines' WHEN 'old' THEN 'measured on the old machine, the new one by the characters between' WHEN 'new' THEN 'measured on the new machine, the old one by the characters between' WHEN 'table' THEN 'from both machines'' compiled sort tables' END || '|' || CASE WHEN r = o THEN 'like the OLD machine' WHEN r = n THEN 'like the NEW machine' ELSE 'like NEITHER machine' END
FROM (SELECT id, o, n, m, CASE WHEN a < b COLLATE "ko_KR" THEN '<' WHEN a > b COLLATE "ko_KR" THEN '>' ELSE '=' END AS r
      FROM (VALUES
(1503, 'ed9ea3', 'e4bcbd', '>', '<', 'both')
      ) AS v(id, ah, bh, o, n, m)
      CROSS JOIN LATERAL (SELECT convert_from(decode(ah, 'hex'), 'UTF8') AS a, convert_from(decode(bh, 'hex'), 'UTF8') AS b) AS s) AS t
ORDER BY id;
\else
\echo 'collation|ko_KR|CANNOT BE USED'
\endif
